# file: .authormark/authormark.mjs
# function: loadConfig  (lines 63-67, javascript)
# called by: .authormark/authormark.mjs::cmdStamp, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdSeal, .authormark/authormark.mjs::cmdVerify, .authormark/authormark.mjs::cmdScan, .authormark/authormark.mjs::cmdImage
# calls: .authormark/authormark.mjs::die
# calls (outside the repo): join, existsSync, parse, readFileSync
# doc: // ---------------------------------------------------------------- config + key
function loadConfig() {
  const p = path.join(CWD, CONFIG_FILE);
  if (!fs.existsSync(p)) die(`no ${CONFIG_FILE} here -- run:  authormark init`);
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

# file: .authormark/authormark.mjs
# function: keyPath  (lines 69-71, javascript)
# called by: .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::cmdInit, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdScan
# calls (outside the repo): homedir
function keyPath(cfg) {
  return (cfg.keyFile || '~/.authormark.key').replace(/^~/, os.homedir());
}

# file: .authormark/authormark.mjs
# function: loadKey  (lines 73-77, javascript)
# called by: .authormark/authormark.mjs::cmdStamp, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdSeal, .authormark/authormark.mjs::cmdVerify, .authormark/authormark.mjs::cmdScan, .authormark/authormark.mjs::cmdImage
# calls: .authormark/authormark.mjs::keyPath, .authormark/authormark.mjs::die
# calls (outside the repo): existsSync, from, readFileSync
function loadKey(cfg) {
  const p = keyPath(cfg);
  if (!fs.existsSync(p)) die(`secret key missing at ${p} -- run:  authormark init`);
  return Buffer.from(fs.readFileSync(p, 'utf8').trim(), 'hex');
}

# file: .authormark/authormark.mjs
# function: canonical  (lines 81-83, javascript)
# called by: .authormark/authormark.mjs::fingerprint
# calls (outside the repo): replace
# doc: // Canonical form: what the fingerprint is computed over. Survives CRLF churn, // trailing whitespace and blank-line drift, so cosmetic edits don't void the mark.
function canonical(text) {
  return text.replace(/\r\n?/g, '\n').split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n').replace(/\n+$/, '') + '\n';
}

# file: .authormark/authormark.mjs
# function: fingerprint  (lines 85-87, javascript)
# called by: .authormark/authormark.mjs::cmdStamp, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdScan
# calls: .authormark/authormark.mjs::canonical
# calls (outside the repo): createHmac
function fingerprint(key, body) {
  return crypto.createHmac('sha256', key).update(canonical(body)).digest('base64url').slice(0, 22);
}

# file: .authormark/authormark.mjs
# function: headerLines  (lines 91-100, javascript)
# called by: .authormark/authormark.mjs::renderHeader
# calls (outside the repo): push
# doc: // ---------------------------------------------------------------- header build / strip
function headerLines(cfg, fp) {
  const l = [
    `${SENTINEL} ${NOREMOVE} (authorship watermark)`,
    `Copyright (c) ${cfg.year} ${cfg.author}${cfg.email ? ` <${cfg.email}>` : ''}`,
    `Author: ${cfg.github}`,
  ];
  if (cfg.license) l.push(`SPDX-License-Identifier: ${cfg.license}`);
  l.push(`${FP_LABEL}${fp}`);
  return l;
}

# file: .authormark/authormark.mjs
# function: renderHeader  (lines 102-107, javascript)
# called by: .authormark/authormark.mjs::cmdStamp
# calls: .authormark/authormark.mjs::headerLines, .authormark/authormark.mjs::zwEncode
# calls (outside the repo): map
function renderHeader(cfg, fp, style, zw) {
  let lines = headerLines(cfg, fp);
  if (zw) lines[0] += zwEncode(fp);
  if (style.prefix) return lines.map(l => style.prefix + l).join('\n') + '\n';
  return [style.open, ...lines.map(l => style.line + l), style.close].join('\n') + '\n';
}

# file: .authormark/authormark.mjs
# function: splitHeader  (lines 110-119, javascript)
# called by: .authormark/authormark.mjs::cmdStamp, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdScan
# calls (outside the repo): split, findIndex, /^\s, includes, slice
# doc: // Returns {header, body} -- header is '' when the file is unstamped.
function splitHeader(text) {
  const lines = text.split('\n');
  const i = lines.findIndex(isHeaderLine);
  if (i === -1) return { header: '', body: text, at: -1 };
  let start = i, end = i;
  if (i > 0 && /^\s*(\/\*!?|<!--)\s*$/.test(lines[i - 1])) start = i - 1;
  while (end < lines.length && !lines[end].includes(FP_LABEL)) end++;
  if (end < lines.length - 1 && /^\s*(\*\/|-->)\s*$/.test(lines[end + 1])) end++;
  return { header: lines.slice(start, end + 1).join('\n'), body: lines.slice(0, start).concat(lines.slice(end + 1)).join('\n'), at: start };
}

# file: .authormark/authormark.mjs
# function: insertIndex  (lines 123-132, javascript)
# called by: .authormark/authormark.mjs::cmdStamp
# calls (outside the repo): split, findIndex, slice, startsWith, /^\s
# doc: // Where the header may legally go: after a shebang, doctype, xml prolog, or a // YAML front-matter block (Jekyll pages and issue templates break if displaced).
function insertIndex(text) {
  const lines = text.split('\n');
  if (lines[0] === '---') {
    const close = lines.findIndex((l, i) => i > 0 && (l === '---' || l === '...'));
    if (close > 0) return lines.slice(0, close + 1).join('\n').length + 1;
  }
  if (lines[0]?.startsWith('#!')) return lines[0].length + 1;
  if (/^\s*(<\?xml|<!doctype)/i.test(lines[0] || '')) return lines[0].length + 1;
  return 0;
}

# file: .authormark/authormark.mjs
# function: zwEncode  (lines 138-141, javascript)
# called by: .authormark/authormark.mjs::renderHeader
# calls (outside the repo): from, toString, map
function zwEncode(s) {
  const bits = [...Buffer.from(s, 'utf8')].map(b => b.toString(2).padStart(8, '0')).join('');
  return ZWB + [...bits].map(b => (b === '1' ? ZW1 : ZW0)).join('') + ZWB;
}

# file: .authormark/authormark.mjs
# function: zwDecode  (lines 143-154, javascript)
# called by: .authormark/authormark.mjs::cmdScan
# calls (outside the repo): RegExp, exec, map, push, parseInt, slice, from
function zwDecode(text) {
  const out = [];
  const re = new RegExp(`${ZWB}([${ZW0}${ZW1}]+)${ZWB}`, 'g');
  let m;
  while ((m = re.exec(text))) {
    const bits = [...m[1]].map(c => (c === ZW1 ? '1' : '0')).join('');
    const bytes = [];
    for (let i = 0; i + 8 <= bits.length; i += 8) bytes.push(parseInt(bits.slice(i, i + 8), 2));
    out.push(Buffer.from(bytes).toString('utf8'));
  }
  return out;
}

# file: .authormark/authormark.mjs
# function: walk  (lines 158-167, javascript)
# called by: .authormark/authormark.mjs::walk, .authormark/authormark.mjs::collect, repo2graph/walker.py::_walk_files
# calls: .authormark/authormark.mjs::walk
# calls (outside the repo): statSync, isFile, includes, extname, has, basename, push, readdirSync, startsWith, join
# doc: // ---------------------------------------------------------------- file walking
function walk(target, exts, acc = []) {
  const st = fs.statSync(target);
  if (st.isFile()) { if (exts.includes(path.extname(target)) || NAMED_FILES.has(path.basename(target))) acc.push(target); return acc; }
  for (const e of fs.readdirSync(target, { withFileTypes: true })) {
    if (e.name.startsWith('.') && e.name !== '.github') continue;
    if (SKIP_DIRS.has(e.name)) continue;
    walk(path.join(target, e.name), exts, acc);
  }
  return acc;
}

# file: .authormark/authormark.mjs
# function: ignored  (lines 170-175, javascript)
# called by: .authormark/authormark.mjs::collect, .authormark/authormark.mjs::cmdCheck
# calls (outside the repo): split, some, has, slice, startsWith, replace
# doc: // Never enforce marks on generated output or vendored/third-party content.
function ignored(rel, cfg) {
  const segs = rel.split(path.sep).join('/').split('/');
  if (segs.some(s => SKIP_DIRS.has(s))) return true;
  if (segs.slice(0, -1).some(s => s.startsWith('.') && s !== '.github')) return true;
  return (cfg?.ignore || []).some(p => rel === p || rel.startsWith(p.replace(/\/+$/, '') + '/'));
}

# file: .authormark/authormark.mjs
# function: collect  (lines 177-188, javascript)
# called by: .authormark/authormark.mjs::cmdStamp, .authormark/authormark.mjs::cmdCheck, .authormark/authormark.mjs::cmdSeal
# calls: .authormark/authormark.mjs::warn, .authormark/authormark.mjs::walk, .authormark/authormark.mjs::ignored
# calls (outside the repo): Set, existsSync, relative, add, sort
function collect(paths, exts, cfg) {
  const targets = paths.length ? paths : ['.'];
  const files = new Set();
  for (const t of targets) {
    if (!fs.existsSync(t)) { warn(`skip (missing): ${t}`); continue; }
    for (const f of walk(t, exts)) {
      const rel = path.relative(CWD, f);
      if (!ignored(rel, cfg)) files.add(rel);
    }
  }
  return [...files].sort();
}

# file: .authormark/authormark.mjs
# function: cmdInit  (lines 192-208, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::flag, .authormark/authormark.mjs::tryGit, .authormark/authormark.mjs::keyPath, .authormark/authormark.mjs::log
# calls (outside the repo): new Date, Date, writeFileSync, join, stringify, existsSync, randomBytes
# doc: // ---------------------------------------------------------------- commands
function cmdInit(args) {
  const author = flag(args, '--author') || tryGit('user.name') || 'Srinivasan-78';
  const email = flag(args, '--email') || tryGit('user.email') || '';
  const github = flag(args, '--github') || 'https://github.com/Srinivasan-78';
  const license = flag(args, '--license') || 'MIT';
  const cfg = { author, email, github, year: new Date().getFullYear(), license, keyFile: '~/.authormark.key', ignore: [] };
  fs.writeFileSync(path.join(CWD, CONFIG_FILE), JSON.stringify(cfg, null, 2) + '\n');
  const kp = keyPath(cfg);
  if (fs.existsSync(kp)) {
    log(`key kept: ${kp} (already exists -- never regenerate, old fingerprints would break)`);
  } else {
    fs.writeFileSync(kp, crypto.randomBytes(32).toString('hex') + '\n', { mode: 0o600 });
    log(`key created: ${kp}  (chmod 600 -- BACK THIS UP, it is your proof of authorship)`);
  }
  log(`config written: ${CONFIG_FILE}`);
  log(`\nnext:  authormark stamp app components lib`);
}

# file: .authormark/authormark.mjs
# function: cmdStamp  (lines 210-233, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::loadConfig, .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::flag, .authormark/authormark.mjs::collect, .authormark/authormark.mjs::positional, .authormark/authormark.mjs::styleFor, .authormark/authormark.mjs::splitHeader, .authormark/authormark.mjs::fingerprint, .authormark/authormark.mjs::renderHeader, .authormark/authormark.mjs::insertIndex, .authormark/authormark.mjs::log
# calls (outside the repo): startsWith, includes, readFileSync, replace, slice, writeFileSync
function cmdStamp(args) {
  const cfg = loadConfig(), key = loadKey(cfg);
  const exts = flag(args, '--ext')?.split(',').map(e => (e.startsWith('.') ? e : '.' + e)) || DEFAULT_EXTS;
  const zw = args.includes('--zw');
  const dry = args.includes('--dry');
  const files = collect(positional(args), exts, cfg);
  let added = 0, refreshed = 0, same = 0;

  for (const rel of files) {
    const orig = fs.readFileSync(rel, 'utf8');
    const style = styleFor(rel);
    const { header, body } = splitHeader(orig);
    const fp = fingerprint(key, body);
    const next = renderHeader(cfg, fp, style, zw);
    if (header && header + '\n' === next.replace(/\n$/, '') + '\n') { same++; continue; }
    const at = insertIndex(body);
    const out = body.slice(0, at) + next + body.slice(at);
    if (out === orig) { same++; continue; }
    if (!dry) fs.writeFileSync(rel, out);
    header ? refreshed++ : added++;
    if (dry) log(`would ${header ? 'refresh' : 'stamp'}: ${rel}`);
  }
  log(`${dry ? '[dry] ' : ''}stamped ${added}, refreshed ${refreshed}, unchanged ${same}  (${files.length} files)`);
}

# file: .authormark/authormark.mjs
# function: cmdCheck  (lines 235-266, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::loadConfig, .authormark/authormark.mjs::keyPath, .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::flag, .authormark/authormark.mjs::ignored, .authormark/authormark.mjs::collect, .authormark/authormark.mjs::positional, .authormark/authormark.mjs::splitHeader, .authormark/authormark.mjs::fingerprint, .authormark/authormark.mjs::log
# calls (outside the repo): includes, existsSync, startsWith, execFileSync, extname, has, basename, readFileSync, push, match, error, exit
function cmdCheck(args) {
  const cfg = loadConfig();
  // CI has no access to the secret key, so fall back to presence-only checking
  // there: it still blocks a stripped header, it just can't validate the HMAC.
  const presence = args.includes('--presence') || !fs.existsSync(keyPath(cfg));
  const key = presence ? null : loadKey(cfg);
  const exts = flag(args, '--ext')?.split(',').map(e => (e.startsWith('.') ? e : '.' + e)) || DEFAULT_EXTS;
  let files;
  if (args.includes('--staged')) {
    files = execFileSync('git', ['diff', '--cached', '--name-only', '--diff-filter=ACM'], { encoding: 'utf8' })
      .split('\n')
      .filter(f => f && (exts.includes(path.extname(f)) || NAMED_FILES.has(path.basename(f))) && !ignored(f, cfg) && fs.existsSync(f));
  } else {
    files = collect(positional(args), exts, cfg);
  }
  const missing = [], tampered = [];
  for (const rel of files) {
    const text = fs.readFileSync(rel, 'utf8');
    const { header, body } = splitHeader(text);
    if (!header) { missing.push(rel); continue; }
    if (!key) continue;
    const claimed = header.match(/Fingerprint: AMK1\.([A-Za-z0-9_-]{22})/)?.[1];
    if (claimed !== fingerprint(key, body)) tampered.push(rel);
  }
  for (const f of missing) console.error(`  MISSING watermark: ${f}`);
  for (const f of tampered) console.error(`  STALE fingerprint:  ${f}  (re-run: authormark stamp ${f})`);
  if (missing.length || tampered.length) {
    console.error(`\nauthormark: ${missing.length} unmarked, ${tampered.length} stale of ${files.length}.`);
    process.exit(1);
  }
  log(`authormark: all ${files.length} files carry a watermark${presence ? ' (presence only -- no key here, fingerprints not verified).' : ' with a valid fingerprint.'}`);
}

# file: .authormark/authormark.mjs
# function: cmdSeal  (lines 268-293, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::loadConfig, .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::flag, .authormark/authormark.mjs::collect, .authormark/authormark.mjs::positional, .authormark/authormark.mjs::log
# calls (outside the repo): startsWith, map, readFileSync, createHash, new Date, Date, createHmac, writeFileSync, join, stringify
function cmdSeal(args) {
  const cfg = loadConfig(), key = loadKey(cfg);
  const exts = flag(args, '--ext')?.split(',').map(e => (e.startsWith('.') ? e : '.' + e)) || DEFAULT_EXTS;
  const files = collect(positional(args), exts, cfg);
  const entries = files.map(rel => {
    const buf = fs.readFileSync(rel);
    return { path: rel, sha256: crypto.createHash('sha256').update(buf).digest('hex'), bytes: buf.length };
  });
  const digest = crypto.createHash('sha256')
    .update(entries.map(e => `${e.sha256}  ${e.path}`).join('\n')).digest('hex');
  const manifest = {
    schema: 'authormark/manifest/1',
    author: cfg.author, email: cfg.email, github: cfg.github,
    sealedAt: new Date().toISOString(),
    fileCount: entries.length,
    digest,
    proof: crypto.createHmac('sha256', key).update(digest).digest('hex'),
    files: entries,
  };
  fs.writeFileSync(path.join(CWD, MANIFEST_FILE), JSON.stringify(manifest, null, 2) + '\n');
  log(`sealed ${entries.length} files -> ${MANIFEST_FILE}`);
  log(`digest: ${digest}`);
  log(`\nnotarize it (free, public, timestamped):`);
  log(`  gpg --armor --detach-sign ${MANIFEST_FILE}      # if you have a GPG key`);
  log(`  ots stamp ${MANIFEST_FILE}                      # OpenTimestamps -> bitcoin-anchored proof`);
}

# file: .authormark/authormark.mjs
# function: cmdVerify  (lines 295-312, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::loadConfig, .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::positional, .authormark/authormark.mjs::log
# calls (outside the repo): parse, readFileSync, createHash, map, createHmac, existsSync, error, exit
function cmdVerify(args) {
  const cfg = loadConfig(), key = loadKey(cfg);
  const file = positional(args)[0] || MANIFEST_FILE;
  const m = JSON.parse(fs.readFileSync(file, 'utf8'));
  const digest = crypto.createHash('sha256')
    .update(m.files.map(e => `${e.sha256}  ${e.path}`).join('\n')).digest('hex');
  const proofOk = m.proof === crypto.createHmac('sha256', key).update(digest).digest('hex');
  log(`manifest digest: ${digest === m.digest ? 'OK' : 'MISMATCH'}`);
  log(`your HMAC proof: ${proofOk ? 'OK -- this manifest was sealed with your key' : 'FAIL -- not sealed by your key'}`);
  let changed = 0, missing = 0;
  for (const e of m.files) {
    if (!fs.existsSync(e.path)) { missing++; console.error(`  gone:    ${e.path}`); continue; }
    const h = crypto.createHash('sha256').update(fs.readFileSync(e.path)).digest('hex');
    if (h !== e.sha256) { changed++; console.error(`  changed: ${e.path}`); }
  }
  log(`${m.fileCount} sealed, ${changed} changed, ${missing} gone since ${m.sealedAt}`);
  if (!proofOk || digest !== m.digest) process.exit(1);
}

# file: .authormark/authormark.mjs
# function: cmdScan  (lines 314-334, javascript)
# entry point: nothing in this repo calls it — a flow starts here
# calls: .authormark/authormark.mjs::loadConfig, .authormark/authormark.mjs::keyPath, .authormark/authormark.mjs::loadKey, .authormark/authormark.mjs::positional, .authormark/authormark.mjs::log, .authormark/authormark.mjs::scanPng, .authormark/authormark.mjs::scanJpeg, .authormark/authormark.mjs::splitHeader, .authormark/authormark.mjs::fingerprint, .authormark/authormark.mjs::zwDecode
# calls (outside the repo): existsSync, join, readFileSync, extname, toString, split, trim, match
function cmdScan(args) {
  const cfg = fs.existsSync(path.join(CWD, CONFIG_FILE)) ? loadConfig() : null;
  const key = cfg && fs.existsSync(keyPath(cfg)) ? loadKey(cfg) : null;
  for (const f of positional(args)) {
    log(`\n=== ${f}`);
    const buf = fs.readFileSync(f);
    const ext = path.extname(f).toLowerCase();
    if (ext === '.png') { scanPng(buf, key); continue; }
    if (ext === '.jpg' || ext === '.jpeg') { scanJpeg(buf); continue; }
    const text = buf.toString('utf8');
    const { header, body } = splitHeader(text);
    if (header) {
      log(header.split('\n').map(l => '  ' + l.trim()).join('\n'));
      const claimed = header.match(/Fingerprint: AMK1\.([A-Za-z0-9_-]{22})/)?.[1];
      if (key) log(`  -> fingerprint ${claimed === fingerprint(key, body) ? 'VALID for your key' : 'does NOT match current content'}`);
    } else log('  no visible header');
    const zw = zwDecode(text);
    if (zw.length) log(`  hidden zero-width mark(s): ${zw.join(', ')}`);
    else log('  no zero-width mark');
  }
}

# file: .authormark/authormark.mjs
# function: crc32  (lines 344-348, javascript)
# called by: .authormark/authormark.mjs::pngSerialize, .authormark/authormark.mjs::lsbEmbed, .authormark/authormark.mjs::lsbExtract
function crc32(buf) {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

# file: .authormark/authormark.mjs
# function: pngChunks  (lines 350-361, javascript)
# called by: .authormark/authormark.mjs::decodePng, .authormark/authormark.mjs::scanPng
# calls: .authormark/authormark.mjs::die
# calls (outside the repo): readUInt32BE, toString, push, subarray
function pngChunks(buf) {
  if (buf.readUInt32BE(0) !== 0x89504e47) die('not a PNG');
  const out = [];
  let p = 8;
  while (p < buf.length) {
    const len = buf.readUInt32BE(p);
    const type = buf.toString('ascii', p + 4, p + 8);
    out.push({ type, data: buf.subarray(p + 8, p + 8 + len) });
    p += 12 + len;
  }
  return out;
}

# file: .authormark/authormark.mjs
# function: pngSerialize  (lines 363-372, javascript)
# called by: .authormark/authormark.mjs::encodePng
# calls: .authormark/authormark.mjs::crc32
# calls (outside the repo): from, alloc, writeUInt32BE, concat, push
function pngSerialize(chunks) {
  const parts = [Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])];
  for (const c of chunks) {
    const len = Buffer.alloc(4); len.writeUInt32BE(c.data.length);
    const body = Buffer.concat([Buffer.from(c.type, 'ascii'), c.data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body));
    parts.push(len, body, crc);
  }
  return Buffer.concat(parts);
}

# file: .authormark/authormark.mjs
